1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.List;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.MissingFieldsException;
8	
9	/**
10	 * Strips every non-digit from the telephone and requires exactly 10 digits, storing the
11	 * normalized value back on the request so it is persisted and returned as {@code telephone}.
12	 * A non-conforming number is rejected with 400 via {@link MissingFieldsException}.
13	 */
14	public class NormalizeTelephone {
15	
16	    public void service(@Val OwnerFieldsDto request) throws MissingFieldsException {
17	        String digits = request.getTelephone().replaceAll("\\D", "");
18	        if (digits.length() != 10) {
19	            throw new MissingFieldsException(List.of("telephone"));
20	        }
21	        request.setTelephone(digits);
22	    }
23	}
