1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.List;
4	import java.util.Locale;
5	import java.util.regex.Pattern;
6	
7	import net.officefloor.plugin.variable.Val;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	import org.springframework.samples.petclinic.rest.escalation.MissingFieldsException;
10	
11	/**
12	 * When an email is present it must be a syntactically valid address; it is stored back on the
13	 * request lower-cased so it is persisted and returned as {@code email}. A malformed address is
14	 * rejected with 400 via {@link MissingFieldsException}. An absent email is left untouched.
15	 */
16	public class NormalizeEmail {
17	
18	    private static final Pattern EMAIL = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
19	
20	    public void service(@Val OwnerFieldsDto request) throws MissingFieldsException {
21	        String email = request.getEmail();
22	        if (email == null || email.isBlank()) {
23	            return;
24	        }
25	        if (!EMAIL.matcher(email).matches()) {
26	            throw new MissingFieldsException(List.of("email"));
27	        }
28	        request.setEmail(email.toLowerCase(Locale.ROOT));
29	    }
30	}
