1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateTelephoneException;
8	
9	/**
10	 * Rejects a create request whose (already normalized) telephone matches any existing owner's
11	 * normalized telephone, so a duplicate number is a 409 via {@link DuplicateTelephoneException}.
12	 */
13	public class EnsureUniqueTelephone {
14	
15	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
16	            throws DuplicateTelephoneException {
17	        String telephone = request.getTelephone();
18	        for (Owner owner : ownerRepository.findAll()) {
19	            if (telephone.equals(normalize(owner.getTelephone()))) {
20	                throw new DuplicateTelephoneException(telephone);
21	            }
22	        }
23	    }
24	
25	    private static String normalize(String telephone) {
26	        return telephone == null ? null : telephone.replaceAll("\\D", "");
27	    }
28	}
